def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'
    if n < 8:
        return 'D' if history[-1][1] == 'D' else 'C'

    last_me, last_opp = history[-1]
    prev_me, prev_opp = history[-2]

    opp_c = 0
    my_c = 0
    r10_c = 0
    start10 = n - 10 if n >= 10 else 0

    for i in range(n):
        m, o = history[i]
        if o == 'C':
            opp_c += 1
            if i >= start10:
                r10_c += 1
        if m == 'C':
            my_c += 1

    opp_d = n - opp_c
    my_d = n - my_c

    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    opp_streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_streak_c += 1
        else:
            break

    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak_d += 1
        else:
            break

    total_after_c = 0
    c_after_c = 0
    total_after_d = 0
    c_after_d = 0

    for i in range(n - 1):
        if history[i][0] == 'C':
            total_after_c += 1
            if history[i + 1][1] == 'C':
                c_after_c += 1
        else:
            total_after_d += 1
            if history[i + 1][1] == 'C':
                c_after_d += 1

    if opp_c == 0:
        return 'D'

    if last_opp == 'D' and prev_opp == 'C' and prev_me == 'D':
        if (opp_d * 2 >= n) or (opp_streak_d >= 3) or (r10_c <= 3):
            return 'D'
        return 'C'

    if opp_d == 0 and total_after_d >= 1 and c_after_d == total_after_d and last_opp == 'C':
        return 'D'

    if (n >= 20 and opp_d * 10 <= n and r10_c >= 9 and
            total_after_d >= 3 and c_after_d == total_after_d and last_opp == 'C'):
        return 'D'

    hostile = (opp_d * 2 >= n) or (opp_streak_d >= 4) or (r10_c <= 2)

    if hostile:
        if last_opp == 'C' and opp_streak_c >= 6 and my_streak_d >= 4 and r10_c >= 6:
            return 'C'
        return 'D'

    friend = (opp_d <= max(2, n // 8)) and (r10_c >= 7)

    if friend:
        if last_opp == 'D':
            return 'D'

        if last_me == 'D':
            return 'C'

        if (n >= 25 and n < 94 and
                opp_d <= max(1, n // 10) and
                r10_c >= 9 and
                my_d <= max(1, n // 10) and
                rng.random() < 0.014):
            return 'D'

        return 'C'

    if last_opp == 'D':
        if last_me == 'D' and opp_streak_d <= 2 and r10_c >= 5:
            return 'C'
        return 'D'

    if last_me == 'D':
        if total_after_d >= 4 and c_after_d * 10 >= total_after_d * 8 and r10_c >= 8:
            return 'D'
        return 'C'

    if total_after_c >= 8:
        bad_after_c = total_after_c - c_after_c
        if bad_after_c * 4 >= total_after_c and r10_c <= 8:
            return 'D'

    if r10_c <= 3 or (opp_d > my_d + n // 3):
        return 'D'

    return 'C'
